package com.example.governance.dataobject;

import com.example.governance.assets.DataSourceStore;
import com.example.governance.assets.ExecutionDataSourceProvider;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

/** A persisted, single-use DDL preview. Remote DDL is never presumed transactional. */
@Service
public class ObjectSchemaService {
    public record Request(List<ObjectDialect.Field> fields) {}
    public record Plan(String operationId, ObjectStore.Identity identity, List<ObjectDialect.Change> changes, String status) {}
    private record Saved(long objectId,List<ObjectDialect.Field> fields) {}
    private final JdbcTemplate jdbc; private final ObjectStore store; private final ObjectMetadata metadata;
    private final DataSourceStore sources; private final ExecutionDataSourceProvider connections; private final ObjectMapper mapper; private final TransactionTemplate tx;private final ObjectOperationGuard guard;
    public ObjectSchemaService(JdbcTemplate jdbc,ObjectStore store,ObjectMetadata metadata,DataSourceStore sources,ExecutionDataSourceProvider connections,ObjectMapper mapper,PlatformTransactionManager manager,ObjectOperationGuard guard){this.jdbc=jdbc;this.store=store;this.metadata=metadata;this.sources=sources;this.connections=connections;this.mapper=mapper;this.tx=new TransactionTemplate(manager);this.guard=guard;}
    private String fingerprint(List<ObjectStore.Field> fields) throws Exception {return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(mapper.writeValueAsString(fields).getBytes(StandardCharsets.UTF_8)));}
    private record MysqlPlan(List<ObjectDialect.Change> changes,String attributes) {}
    private String mysqlLiteral(String value){if(value.length()>1000||value.indexOf('\\')>=0||value.chars().anyMatch(c->c<32))throw new IllegalArgumentException("字段属性包含无法安全表示的字符");return "'"+value.replace("'","''")+"'";}
    /** Read and preserve attributes omitted by JDBC's generic column metadata. */
    private MysqlPlan mysqlPlan(ObjectStore.Identity identity,List<ObjectDialect.Field> before,List<ObjectDialect.Field> target,List<ObjectDialect.Change> changes) throws Exception {
        Map<String,ObjectDialect.Field> old=new HashMap<>();before.forEach(f->old.put(f.name(),f));Set<String> modified=new TreeSet<>();
        for(var f:target){var previous=old.get(f.name());if(previous!=null&&!previous.equals(f))modified.add(f.name());}
        if(modified.isEmpty())return new MysqlPlan(changes,"");
        Map<String,List<String>> attributes=new TreeMap<>();
        String sql="SELECT COLUMN_NAME,COLUMN_DEFAULT,EXTRA,COLUMN_COMMENT,CHARACTER_SET_NAME,COLLATION_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=? AND TABLE_NAME=?";
        try(var connection=connections.get(identity.sourceId()).getConnection();var ps=connection.prepareStatement(sql)){
            ps.setString(1,identity.catalog());ps.setString(2,identity.table());try(var rows=ps.executeQuery()){while(rows.next()){String name=rows.getString(1);if(!modified.contains(name))continue;
                String defaultValue=rows.getString(2),extra=Objects.toString(rows.getString(3),""),comment=Objects.toString(rows.getString(4),""),charset=Objects.toString(rows.getString(5),""),collation=Objects.toString(rows.getString(6),"");
                boolean currentTime=defaultValue!=null&&old.get(name).type().equals("DATETIME")&&defaultValue.matches("(?i)CURRENT_TIMESTAMP(?:\\(\\d\\))?");
                if(!extra.isBlank()&&!(extra.equalsIgnoreCase("DEFAULT_GENERATED")&&currentTime))throw new IllegalArgumentException("字段 "+name+" 包含生成列、自动更新或其他特殊属性，不能安全修改");
                if(!charset.matches("[A-Za-z0-9_]*")||!collation.matches("[A-Za-z0-9_]*")||charset.isEmpty()!=collation.isEmpty())throw new IllegalArgumentException("无法核对字段字符集或排序规则");
                String defaultSql=defaultValue==null?"":currentTime?defaultValue.toUpperCase(Locale.ROOT):mysqlLiteral(defaultValue);
                String commentSql=comment.isEmpty()?"":mysqlLiteral(comment);attributes.put(name,List.of(defaultValue==null?"0":"1",defaultSql,extra,commentSql,charset,collation));}}
        }
        if(attributes.size()!=modified.size())throw new IllegalArgumentException("无法核对 MySQL 字段属性，不能发布");
        List<ObjectDialect.Change> result=new ArrayList<>();var dialect=ObjectDialect.forProfile("MYSQL:8.x");
        for(var change:changes){String statement=change.sql();for(var e:attributes.entrySet()){String marker=" MODIFY COLUMN "+dialect.quoteIdentifier(e.getKey())+" ";if(!statement.contains(marker))continue;var attr=e.getValue();int end=statement.endsWith(" NOT NULL")?statement.length()-9:statement.endsWith(" NULL")?statement.length()-5:-1;if(end<0)throw new IllegalStateException("字段变更语句无效");String character=attr.get(4).isEmpty()?"":" CHARACTER SET "+attr.get(4)+" COLLATE "+attr.get(5);statement=statement.substring(0,end)+character+statement.substring(end)+(attr.get(0).equals("1")?" DEFAULT "+attr.get(1):"")+(attr.get(3).isEmpty()?"":" COMMENT "+attr.get(3));break;}result.add(new ObjectDialect.Change(statement,change.risk()));}
        return new MysqlPlan(List.copyOf(result),mapper.writeValueAsString(attributes));
    }
    private String fingerprint(List<ObjectStore.Field> fields,String attributes) throws Exception {return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest((mapper.writeValueAsString(fields)+"\n"+attributes).getBytes(StandardCharsets.UTF_8)));}
    private List<ObjectDialect.Field> definition(List<ObjectStore.Field> fields){List<ObjectDialect.Field> result=new ArrayList<>();for(var f:fields){if("UNKNOWN".equals(f.nullable())||"UNKNOWN".equals(f.primaryKey()))throw new IllegalArgumentException("字段可空或主键信息未知，不能发布结构");String type=f.type().toUpperCase(Locale.ROOT);Integer length=Set.of("VARCHAR","VARCHAR2","CHAR","DECIMAL","NUMERIC","NUMBER").contains(type)?f.length():null;Integer scale=Set.of("DECIMAL","NUMERIC","NUMBER").contains(type)?f.scale():null;result.add(new ObjectDialect.Field(f.name(),type,length,scale,"YES".equals(f.nullable()),"YES".equals(f.primaryKey())));}return result;}
    public Plan preview(long id,Request request) throws Exception {
        var object=store.find(id);var identity=object.identity();if(!"TABLE".equals(identity.type()))throw new IllegalArgumentException("视图不支持结构发布");if(request==null||request.fields()==null)throw new IllegalArgumentException("字段定义无效");metadata.validateTarget(identity);
        var source=sources.find(identity.sourceId()).orElseThrow(()->new IllegalArgumentException("数据源不存在"));var actual=metadata.fields(identity);var before=definition(actual);String qualifier="MYSQL".equals(source.type())?identity.catalog():identity.schema();var dialect=ObjectDialect.forProfile(source.profileId());
        var changes=dialect.planChanges(new ObjectDialect.Table(qualifier,identity.table(),before),new ObjectDialect.Table(qualifier,identity.table(),request.fields()));
        MysqlPlan mysql="MYSQL".equals(source.type())?mysqlPlan(identity,before,request.fields(),changes):new MysqlPlan(changes,"");changes=mysql.changes();String attributes=mysql.attributes();
        String operation=UUID.randomUUID().toString(),hash=ObjectStore.identityHash(identity),fp=fingerprint(actual,attributes),target=mapper.writeValueAsString(new Saved(id,request.fields()));
        var persistedChanges=changes;try{tx.executeWithoutResult(s->{jdbc.update("DELETE FROM data_object_drafts WHERE object_id=?",id);jdbc.update("INSERT INTO data_object_drafts(object_id,definition_json) VALUES (?,?)",id,target);jdbc.update("INSERT INTO data_object_operations(id,object_id,source_id,identity_hash,active_identity,operation_type,status,target_json,original_fingerprint) VALUES (?,?,?,?,?,'SCHEMA','PREPARED',?,?)",operation,id,identity.sourceId(),hash,hash,target,fp);for(int i=0;i<persistedChanges.size();i++){var c=persistedChanges.get(i);jdbc.update("INSERT INTO data_object_operation_steps(operation_id,step_number,statement_text,risk_text,status) VALUES (?,?,?,?,'PENDING')",operation,i+1,c.sql(),c.risk());}});}catch(DuplicateKeyException e){throw new IllegalStateException("该物理对象已有待处理操作");}
        return new Plan(operation,identity,changes,"PREPARED");
    }
    public record PendingOperation(String operationId,long objectId,String status,String error) {}
    public List<PendingOperation> pending(){return jdbc.query("SELECT id,object_id,status,error_message FROM data_object_operations WHERE operation_type='SCHEMA' AND active_identity IS NOT NULL ORDER BY created_at DESC",(r,n)->new PendingOperation(r.getString(1),r.getLong(2),r.getString(3),r.getString(4)));}
    public List<ObjectStore.Field> inspect(String id) throws Exception {try(var lease=guard.acquire(id)){jdbc.update("UPDATE data_object_operations SET status='UNKNOWN',error_message='执行中断，请核对实际结构',updated_at=CURRENT_TIMESTAMP WHERE id=? AND operation_type='SCHEMA' AND status='EXECUTING'",id);return inspectLocked(id);}}
    private List<ObjectStore.Field> inspectLocked(String id) throws Exception {var entries=pending().stream().filter(p->p.operationId().equals(id)).toList();if(entries.size()!=1||!Set.of("UNKNOWN","PARTIAL").contains(entries.getFirst().status()))throw new IllegalStateException("当前操作不能核对");return metadata.fields(store.find(entries.getFirst().objectId()).identity());}
    public void acknowledge(String id) throws Exception {try(var lease=guard.acquire(id)){acknowledgeLocked(id);}}
    private void acknowledgeLocked(String id) throws Exception {var fields=inspectLocked(id);var entry=pending().stream().filter(p->p.operationId().equals(id)).findFirst().orElseThrow();tx.executeWithoutResult(s->{if(jdbc.update("UPDATE data_object_operations SET status='RECONCILED',active_identity=NULL,updated_at=CURRENT_TIMESTAMP WHERE id=? AND status IN ('UNKNOWN','PARTIAL')",id)!=1)throw new IllegalStateException("操作状态已变化");jdbc.update("DELETE FROM data_object_fields WHERE object_id=?",entry.objectId());for(var f:fields)jdbc.update("INSERT INTO data_object_fields(object_id,ordinal_position,field_name,native_type,field_length,field_scale,nullable_state,primary_key_state,remarks) VALUES (?,?,?,?,?,?,?,?,?)",entry.objectId(),f.ordinal(),f.name(),f.type(),f.length(),f.scale(),f.nullable(),f.primaryKey(),f.remarks());jdbc.update("UPDATE data_objects SET version=version+1,updated_at=CURRENT_TIMESTAMP WHERE id=?",entry.objectId());});}
    public void cancel(String id){if(jdbc.update("UPDATE data_object_operations SET status='CANCELLED',active_identity=NULL,updated_at=CURRENT_TIMESTAMP WHERE id=? AND operation_type='SCHEMA' AND status='PREPARED'",id)!=1)throw new IllegalStateException("只有待执行的预览可以取消");}
    public Plan execute(String id) throws Exception {try(var lease=guard.acquire(id)){return executeLocked(id);}}
    private Plan executeLocked(String id) throws Exception {
        var records=jdbc.queryForList("SELECT object_id,target_json,original_fingerprint,status FROM data_object_operations WHERE id=? AND operation_type='SCHEMA'",id);if(records.isEmpty())throw new IllegalArgumentException("操作不存在");var record=records.getFirst();if(!"PREPARED".equals(record.get("status")))throw new IllegalStateException("操作状态已变化，请刷新");long objectId=((Number)record.get("object_id")).longValue();var object=store.find(objectId);var identity=object.identity();var saved=mapper.readValue((String)record.get("target_json"),Saved.class);if(saved.objectId()!=objectId)throw new IllegalStateException("操作记录无效");metadata.validateTarget(identity);
        var source=sources.find(identity.sourceId()).orElseThrow();var actual=metadata.fields(identity);String qualifier="MYSQL".equals(source.type())?identity.catalog():identity.schema();var changes=ObjectDialect.forProfile(source.profileId()).planChanges(new ObjectDialect.Table(qualifier,identity.table(),definition(actual)),new ObjectDialect.Table(qualifier,identity.table(),saved.fields()));MysqlPlan mysql="MYSQL".equals(source.type())?mysqlPlan(identity,definition(actual),saved.fields(),changes):new MysqlPlan(changes,"");changes=mysql.changes();String attributes=mysql.attributes();if(!fingerprint(actual,attributes).equals(record.get("original_fingerprint"))){jdbc.update("UPDATE data_object_operations SET status='STALE',active_identity=NULL,updated_at=CURRENT_TIMESTAMP WHERE id=? AND status='PREPARED'",id);throw new IllegalStateException("物理表结构已变化，请刷新并重新预览");}
        var persisted=jdbc.query("SELECT statement_text,risk_text FROM data_object_operation_steps WHERE operation_id=? ORDER BY step_number",(r,n)->new ObjectDialect.Change(r.getString(1),r.getString(2)),id);if(!changes.equals(persisted))throw new IllegalStateException("预览内容已变化，请重新预览");
        if(jdbc.update("UPDATE data_object_operations SET status='EXECUTING',updated_at=CURRENT_TIMESTAMP WHERE id=? AND status='PREPARED'",id)!=1)throw new IllegalStateException("操作已执行或正在执行");
        int completed=0;try(var connection=connections.get(identity.sourceId()).getConnection();var statement=connection.createStatement()){statement.setQueryTimeout(30);for(int i=0;i<changes.size();i++){jdbc.update("UPDATE data_object_operation_steps SET status='EXECUTING' WHERE operation_id=? AND step_number=?",id,i+1);statement.execute(changes.get(i).sql());jdbc.update("UPDATE data_object_operation_steps SET status='SUCCEEDED' WHERE operation_id=? AND step_number=?",id,i+1);completed++;}}
        catch(Exception e){try{metadata.fields(identity);}catch(Exception ignored){}String status=completed>0?"PARTIAL":"UNKNOWN";jdbc.update("UPDATE data_object_operations SET status=?,error_message='结构执行结果待核实，请重新读取物理表',updated_at=CURRENT_TIMESTAMP WHERE id=?",status,id);return new Plan(id,identity,changes,status);}
        try{var updated=metadata.fields(identity);var actualDefinition=definition(updated);if(actualDefinition.size()!=saved.fields().size())throw new IllegalStateException("结构核对不一致");for(int i=0;i<actualDefinition.size();i++){var a=actualDefinition.get(i);var expected=saved.fields().get(i);if(!new ObjectDialect.Field(expected.name(),expected.type(),expected.length(),expected.scale(),expected.nullable(),expected.primaryKey()).equals(a)||expected.remarks()!=null&&!expected.remarks().isEmpty()&&!expected.remarks().equals(updated.get(i).remarks()))throw new IllegalStateException("结构核对不一致");}tx.executeWithoutResult(s->{jdbc.update("DELETE FROM data_object_fields WHERE object_id=?",objectId);for(var f:updated)jdbc.update("INSERT INTO data_object_fields(object_id,ordinal_position,field_name,native_type,field_length,field_scale,nullable_state,primary_key_state,remarks) VALUES (?,?,?,?,?,?,?,?,?)",objectId,f.ordinal(),f.name(),f.type(),f.length(),f.scale(),f.nullable(),f.primaryKey(),f.remarks());jdbc.update("UPDATE data_objects SET version=version+1,updated_at=CURRENT_TIMESTAMP WHERE id=?",objectId);jdbc.update("DELETE FROM data_object_drafts WHERE object_id=?",objectId);jdbc.update("UPDATE data_object_operations SET status='SUCCEEDED',active_identity=NULL,updated_at=CURRENT_TIMESTAMP WHERE id=?",id);});return new Plan(id,identity,changes,"SUCCEEDED");}catch(Exception e){jdbc.update("UPDATE data_object_operations SET status='UNKNOWN',error_message='发布后结构需要核实',updated_at=CURRENT_TIMESTAMP WHERE id=?",id);return new Plan(id,identity,changes,"UNKNOWN");}
    }
}
